#!/usr/bin/env node
import { dirname } from "node:path";
import { argv, exit, version } from "node:process";
import { fileURLToPath } from "node:url";
import { absPath, fsExtra } from "@yangzw/bruce-us/node";
import { Command } from "commander";
import Semver from "semver";

import { ACTION_TEXT, CMD_TEXT } from "./langs";
import { Init, Update } from "./libs";

if (Semver.lt(version, "v22.0.0")) {
	console.log(CMD_TEXT.judgeNode);
	exit(1);
}

const program = new Command();
const root = dirname(fileURLToPath(import.meta.url));
const packagePath = absPath("../package.json", root);
const { version: packageVersion = "2.0.0" } = fsExtra.readJsonSync(packagePath, "utf8") ?? {};

program
	.name(CMD_TEXT.cmd)
	.usage("<command>")
	.description(CMD_TEXT.desc)
	.version(CMD_TEXT.version(packageVersion), "-v, --version", ACTION_TEXT.version)
	.helpOption("-h, --help", ACTION_TEXT.help)
	.helpCommand("help [command]", ACTION_TEXT.helpCmd);
program
	.command("init")
	.alias("i")
	.description(ACTION_TEXT.init)
	.action(Init);
program
	.command("update")
	.alias("u")
	.description(ACTION_TEXT.update)
	.action(Update);
program.parse(argv);