import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { normalize } from "node:path";
import { cwd } from "node:process";
import { fsExtra } from "@yangzw/bruce-us/node";
import { applyEdits, modify, parseTree } from "jsonc-parser";

import type { ActionTextType } from "../langs";
import { ACTION_TEXT } from "../langs";

interface GenerateConfigType {
	extensions: Record<string, unknown>
	extensionsPath: string
	flag: boolean
	settings: Record<string, unknown>
	settingsPath: string
}

function execCmd(cmd: string): void {
	try {
		execSync(cmd, { stdio: "inherit" });
	} catch {}
}

