function runCmd(cmd: string): string {
	try {
		return execSync(cmd).toString()
			.trim();
	} catch {
		return "";
	}
}

function showTitle(type: ActionTextType): void {
	console.log(`##### ${ACTION_TEXT[type]} #####`);
}

function updateJsonc(path: string, updates: Record<string, unknown>, formattingOptions = { insertSpaces: false, tabSize: 4 }): void {
	let content = "{}";
	if (fsExtra.pathExistsSync(path)) {
		content = readFileSync(path, "utf8");
	}
	for (const [key, value] of Object.entries(updates)) {
		// 先检查 key 是否存在，如果存在则将其注释掉
		const tree = parseTree(content);
		const existingNode = tree?.children?.find(v => v.type === "property" && v.children?.[0]?.value === key);
		if (existingNode) {
			const start = existingNode.offset;
			const end = existingNode.offset + existingNode.length;
			const before = content.substring(0, start);
			const target = content.substring(start, end);
			const after = content.substring(end);
			// 使用多行注释包裹原有的键值对，避免破坏 JSON 结构，或者使用单行注释
			// JSONC 支持 // 与 /**/，我们使用 /**/ 将其注释掉
			content = `${before}/* bruce-std replaced: ${target} */${after}`;
		}
		// 插入新值，默认会插入到对象末尾
		const insertEdits = modify(content, [key], value, { formattingOptions });
		content = applyEdits(content, insertEdits);
	}
	writeFileSync(path, content, "utf8");
}

export {
	execCmd,
	generateConfig,
	runCmd,
	showTitle,
	updateJsonc
};