export default function Init(): void {
	showTitle("init");
	if (!fsExtra.pathExistsSync("package.json")) {
		console.log(INIT_TEXT.judgePackage);
		exit(1);
	}
	const spinner = Ora(INIT_TEXT.doing).start();
	const { extensions, extensionsPath, settings, settingsPath } = generateConfig();
	let finalPackage = fsExtra.readJsonSync("package.json");
	if (finalPackage?.scripts) {
		finalPackage.scripts.commit = "git add --all . && git-cz";
	} else {
		finalPackage = Object.assign(finalPackage, {
			scripts: { commit: "git add --all . && git-cz" }
		});
	}
	if (finalPackage.config) {
		finalPackage.config.commitizen = {
			"path": "node_modules/cz-customizable"
		};
		finalPackage.config["cz-customizable"] = {
			config: "czrc.cjs"
		};
	} else {
		finalPackage = Object.assign(finalPackage, {
			config: {
				"commitizen": {
					"path": "node_modules/cz-customizable"
				},
				"cz-customizable": { config: "czrc.cjs" }
			}
		});
	}
	fsExtra.ensureDirSync(dirname(extensionsPath));
	fsExtra.ensureDirSync(dirname(settingsPath));
	updateJsonc(extensionsPath, extensions);
	updateJsonc(settingsPath, settings);
	const editorconfigPath = absPath("./.editorconfig");
	const gitignorePath = absPath("./.gitignore");
	const czrcPath = absPath("./czrc.cjs");
	if (!fsExtra.pathExistsSync(editorconfigPath)) {
		writeFileSync(editorconfigPath, editorconfigContent, "utf8");
	}
	if (!fsExtra.pathExistsSync(gitignorePath)) {
		writeFileSync(gitignorePath, gitignoreContent, "utf8");
	}
	if (!fsExtra.pathExistsSync(czrcPath)) {
		writeFileSync(czrcPath, czrcContent, "utf8");
	}
	fsExtra.writeJsonSync("package.json", finalPackage, { spaces: "\t" });
	execCmd("npm i -D commitizen cz-customizable");
	spinner.stop();
	console.log(INIT_TEXT.done);
	exit(0);
}