import { dirname } from "node:path";
import { exit } from "node:process";
import { fsExtra } from "@yangzw/bruce-us/node";
import Ora from "ora";

import { UPDATE_TEXT } from "../langs";
import { generateConfig, showTitle, updateJsonc } from "../utils";

export default function Update(): void {
	showTitle("update");
	const spinner = Ora(UPDATE_TEXT.doing).start();
	const { extensions, extensionsPath, flag, settings, settingsPath } = generateConfig();
	if (flag) {
		fsExtra.ensureDirSync(dirname(extensionsPath));
		fsExtra.ensureDirSync(dirname(settingsPath));
		updateJsonc(extensionsPath, extensions);
		updateJsonc(settingsPath, settings);
	}
	spinner.stop();
	console.log(flag ? UPDATE_TEXT.done : UPDATE_TEXT.undone);
	exit(flag ? 0 : 1);
}